"""Render frozen selection and diagnostic results without fitting or selection."""
import json
from .pipeline import ROOT
from .scenario_study import sha


def write_report(s, directory):
    selection = s['selection']; winner = selection['winner']; challenger = s['challenger']['name']
    lines = ['# Условный масштаб и хвосты ошибки минимума', '',
      '13 октября 2026. Исследование станции Краснодар 34929, весна; сад и место пилота не выбраны.', '',
      'Условная модель уменьшает среднюю ширину, но не повышает покрытие холодных ночей. На валидации она уступила прежнему диапазону. Выбранный исследовательский вариант остаётся risk_5_lower_95; полевая выдача остаётся GFS. Условный вариант показан отдельно как диагностический кандидат, без переключения по контрольным результатам.', '',
      '## Что реализовано', '',
      'Семь новых условных вариантов и два прежних сравнения. Ridge прогнозирует log(1+|ошибка|) либо отдельно log(1+отрицательная часть) и log(1+положительная часть). Регуляризация 10/100. Линейная квантильная модель прогнозирует 5-й и 95-й квантили остатка, L1=0.05/0.2; деревья — те же квантили, 100 деревьев, глубина2, минимум20 ночей в листе, шаг0.05. Квантильные пересечения сортируются, точечный минимум включается в диапазон; калибровочная поправка неотрицательна.',
      'Признаки — 15 уже проверяемых агрегатов температуры, влажности, точки росы, ветра и облачности одного выпуска GFS. Фактическая температура и признак «ночь холодная» при выдаче не читаются. Масштаб ограничен 0.5–9°C до калибровки для устойчивости вычислений; это не ограничение итоговой ширины и не гарантия безопасности.',
      'Остатки для обучения получены на шести последовательных блоках целых ночей: точечная Huber-модель обучается без проверяемого блока. Это исключает подгонку диапазона по слишком оптимистичным ошибкам обучающего прогноза. Блоки ретроспективные внутри обучающих лет; остальные блоки могут быть позднее исключённого, но все предшествуют валидационному году.',
      'Артефакты состоят из JSON с коэффициентами/деревьями, без pickle и исполнения кода при загрузке. Проверяются SHA протокола, исходников, родительских моделей, обучающих данных и артефактов. safe_conditional_prediction отвергает другой сайт, неверные входы/выпуск/горизонт/сезон и сильную экстраполяцию обеих голов. Автоматическая защита или вероятность повреждений не добавлены.', '',
      '## Выбор только по 2023–2024', '',
      'Fit2022 → validation2023; fit2022–23 → validation2024. Валидационная калибровка исключает проверяемую ночь целиком. Другие даты того же сезона доступны, поэтому это ретроспективная диагностика настройки, а не перспективная проверка каждой ночи. Финальные головы обучены на2022–23, калибровка на2024. Неполные факты исключаются без заполнения.',
      'До нового контрольного расчёта заданы ограничения: общее покрытие не ниже прежнего симметричного; ширина тёплых ночей не более105% прежнего симметричного; общая ширина не более105% предыдущего холодного диапазона. Среди допустимых — меньше холодных непокрытий, затем меньше сбалансированный interval score холодных/тёплых, затем ширина. При отсутствии допустимых — прежний симметричный диапазон.', '',
      '| Вариант | Покрытие холодных | Ширина всех, °C | Ширина тёплых, °C | Штраф холодных | Допустим |',
      '|---|---:|---:|---:|---:|---|']
    for name, r in selection['pooled_validation'].items():
        ok = all(selection['gates'][name].values())
        lines.append(f"| {name} | {r['cold_covered']}/{r['cold_nights']} | {r['mean_width_c']:.3f} | {r['warm_mean_width_c']:.3f} | {r['cold_interval_score']:.3f} | {'да' if ok else 'нет'} |")
    lines += ['', f'Выбран {winner}. Лучший допустимый условный кандидат {challenger} отдельно зафиксирован тем же критерием до открытия контрольных данных. Он не заменяет победителя. На семи холодных валидационных ночах: прежний5/7, выбранный7/7, условный6/7. Условные линейные квантили не проходят ограничение ширины тёплых ночей.', '',
      '## Контроль без подбора по 2025–2026', '',
      '| Год | Метод | Покрытие всех | Покрытие холодных | Ширина всех, °C | Ширина холодных, °C | Штраф холодных |',
      '|---|---|---:|---:|---:|---:|---:|']
    names = {'gfs': 'GFS + глобальная ошибка2024', 'legacy_huber': 'Симметричный Huber',
             'previous_cold_range': 'Сохранённый холодный диапазон', 'conditional_challenger': 'Условные хвосты, кандидат'}
    for year, season in s['seasons'].items():
        for name, label in names.items():
            r = season['scores'][name]
            lines.append(f"| {year} | {label} | {r['covered']}/{r['nights']} | {r['cold_covered']}/{r['cold_nights']} | {r['mean_width_c']:.3f} | {r['cold_mean_width_c']:.3f} | {r['cold_interval_score']:.3f} |")
    lines += ['', 'Interval score90: ширина +20×расстояние факта за ближайшей границей; меньше лучше. Для GFS показан исходный минимум с отдельно калиброванной глобальной ошибкой2024, а не собственный вероятностный диапазон GFS.',
      'Условный кандидат в2025 сужает общую ширину6.125→5.910°C и снижает холодный штраф15.532→13.639, но покрытие остаётся3/6. В2026 общая ширина6.136→5.882°C, покрытие холодных остаётся4/4; холодная ширина и штраф растут6.404→7.151°C, общее покрытие снижается84/86→83/86. На холодных ночах диапазон расширяется, хотя на тёплых сужается. Это не устойчивый выигрыш и не основание для замены модели.',
      'Контрольные2025/2026 ранее просмотрены в предыдущих исследованиях. Они не участвуют в новом обучении/калибровке/выборе, но это не новый слепой тест. Валидационный2024 участвует также в финальной калибровке; зависимая погода и малое число холодных событий не позволяют обещать условное90% покрытие.', '',
      '## Сохранение детектора и продукта', '',
      '| Год | Попадания | Пропуски | Ложные тревоги | Масок проверено |', '|---|---:|---:|---:|---:|']
    for year, season in s['seasons'].items():
        d = season['detector']
        lines.append(f"| {year} | {d.get('hits',0)} | {d.get('misses',0)} | {d.get('false_alarms',0)} | {season['detector_masks_verified']} |")
    lines += ['', 'Точечный минимум, каждая14-часовая маска, начало и длительность заморозка проверены на совпадение с прежними артефактами для184 прогнозных ночей. Отсутствующие факты7 ночей не восстановлены. Все сложные случаи и экстраполяции оставлены в исследовательском сравнении, но защищённая выдача их отвергает.',
      'Результат улучшения — воспроизводимая условная модель ошибки и проверка её ограничений. Ближайшая задача для качества — независимые холодные события и перспективный сбор ошибок для выбранного сада после выбора локации. Не повторять подбор на тех же2025/2026, не обещать отсутствие недостатков и не переносить станционную модель в поле.', '',
      '## Воспроизведение', '',
      '    .\\.venv\\Scripts\\python.exe -X utf8 -m agro_checker.conditional_error_study --select-only',
      '    .\\.venv\\Scripts\\python.exe -X utf8 -m agro_checker.conditional_error_challenger --select-only',
      '    .\\.venv\\Scripts\\python.exe -X utf8 -m agro_checker.conditional_error_challenger',
      '    .\\.venv\\Scripts\\python.exe -X utf8 -m agro_checker.conditional_error_report', '',
      'Повторная селекция читает сохранённый выбор и проверяет хеши; не подбирает заново при существующем lock. Первый полный запуск сначала фиксирует выбор и условного кандидата, затем читает контроль.', '',
      'Методологические источники: [Conformalized Quantile Regression,2019](https://papers.neurips.cc/paper_files/paper/2019/file/5103c3584b063c431bd1268e9b5e76fb-Paper.pdf), [QuantileRegressor](https://scikit-learn.org/stable/modules/generated/sklearn.linear_model.QuantileRegressor.html). Гарантии обменяемой выборки из статьи не заявляются для зависимых погодных ночей и настроенной здесь модели.', '',
      'SHA выбора: '+s['selection_sha256']+'.', 'SHA условного кандидата: '+s['challenger_lock_sha256']+'.',
      '[Численные результаты](CONDITIONAL_ERROR_SUMMARY.json). [Прежний диапазон](COLD_INTERVAL_REPORT.md).']
    (directory/'CONDITIONAL_ERROR_REPORT.md').write_text('\n'.join(lines)+'\n', encoding='utf-8')


def build_viewer(s, data_dir):
    path = data_dir/'processed/conditional-error-study/challenger-forecasts.json'
    if sha(path) != s['challenger_forecast_sha256']: raise ValueError('Diagnostic forecast snapshot changed')
    payload = {'summary': s, 'frames': json.loads(path.read_text(encoding='utf-8'))}
    text = (ROOT/'web/conditional-range/index.html').read_text(encoding='utf-8')
    out = ROOT/'dist/conditional-range'; out.mkdir(parents=True, exist_ok=True)
    (out/'index.html').write_text(text.replace('__CONDITIONAL_DATA__', json.dumps(payload, ensure_ascii=False, allow_nan=False).replace('<', '\\u003c')), encoding='utf-8')


if __name__ == '__main__':
    summary = json.loads((ROOT/'docs/CONDITIONAL_ERROR_SUMMARY.json').read_text(encoding='utf-8'))
    write_report(summary, ROOT/'docs'); build_viewer(summary, ROOT/'data')
